"""EcoPlate PostgreSQL schema and migrations (Neon or any PostgreSQL 13+).

This is the PostgreSQL twin of the SQLite schema in `app.py` (meal_records) and `ecoplate_db.py` (everything else).
Table names, column names, CHECK rules, UNIQUE rules, indexes and the one foreign key are the same, so the
application code and the API behave identically on both databases.

How it differs from SQLite (all deliberate, none changes behaviour):
* Ids: `INTEGER GENERATED BY DEFAULT AS IDENTITY` replaces `INTEGER PRIMARY KEY AUTOINCREMENT`.
  "BY DEFAULT" lets old ids be imported as they are; call `sync_sequences()` afterwards.
* Dates and times stay TEXT (YYYY-MM-DD, ISO timestamps), exactly like SQLite, so exports and API output do not change.
* REAL becomes DOUBLE PRECISION (SQLite REAL is 8 bytes; PostgreSQL REAL is only 4).
* Recipient names are unique ignoring upper/lower case (SQLite: COLLATE NOCASE) through a unique index on lower(name).
* The expression in the calendar-notes unique index needs its own brackets in PostgreSQL.

Versioning is independent of SQLite's PRAGMA user_version: applied versions are rows in `schema_migrations`.
`migrate()` runs in ONE transaction (PostgreSQL DDL is transactional) and takes an advisory lock, so several
server workers starting at once cannot race. Migrations are additive; existing data is never altered or dropped.

Nothing here connects by itself: `migrate(db)` is called by app.create_app() with an open connection.
"""
from __future__ import annotations

import logging
from datetime import datetime, timezone

SCHEMA_VERSION = 1
LOCK_KEY = 5_172_040_301            # arbitrary constant; identifies "EcoPlate is migrating" to PostgreSQL
log = logging.getLogger("ecoplate.db")

MEAL_LIST = "('Breakfast','Lunch','Dinner')"
ID = "INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY"

# Tables that have an `id` identity column (used to re-synchronise sequences after an import).
TABLES_WITH_ID = ("meal_records", "surplus_items", "surplus_events", "recipients", "day_context",
                  "anomaly_reviews", "forecast_log")

MIGRATION_1 = [
    # ---- meal_records (SQLite: app.SCHEMA) -------------------------------------------------------------
    f"""CREATE TABLE IF NOT EXISTS meal_records (
        id {ID},
        date TEXT NOT NULL,
        meal TEXT NOT NULL CHECK (meal IN {MEAL_LIST}),
        prepared INTEGER NOT NULL CHECK (prepared >= 1),
        leftovers INTEGER NOT NULL,
        source TEXT NOT NULL DEFAULT 'manual',
        batch TEXT,
        synthetic INTEGER NOT NULL DEFAULT 0 CHECK (synthetic IN (0,1)),
        created_at TEXT NOT NULL,
        CHECK (leftovers >= 0 AND leftovers <= prepared),
        UNIQUE (date, meal)
    )""",
    "CREATE INDEX IF NOT EXISTS idx_records_batch ON meal_records(batch)",
    # ---- surplus register (SQLite: ecoplate_db.MIGRATION_1) --------------------------------------------
    f"""CREATE TABLE IF NOT EXISTS surplus_items (
        id {ID},
        item TEXT NOT NULL CHECK (length(item) BETWEEN 1 AND 80),
        meal TEXT CHECK (meal IS NULL OR meal IN {MEAL_LIST}),
        portions INTEGER NOT NULL CHECK (portions BETWEEN 1 AND 10000),
        service_date TEXT NOT NULL,
        prepared_time TEXT,
        use_by_time TEXT,
        storage TEXT NOT NULL DEFAULT 'unknown'
            CHECK (storage IN ('hot_held','refrigerated','room_temp','frozen','unknown')),
        location TEXT NOT NULL DEFAULT '',
        status TEXT NOT NULL DEFAULT 'pending_review'
            CHECK (status IN ('pending_review','available','reserved','collected','withdrawn')),
        safety_confirmed_by TEXT,
        safety_confirmed_at TEXT,
        recipient_id INTEGER,
        legacy_id TEXT UNIQUE,
        created_at TEXT NOT NULL,
        updated_at TEXT NOT NULL
    )""",
    "CREATE INDEX IF NOT EXISTS idx_surplus_status ON surplus_items(status)",
    "CREATE INDEX IF NOT EXISTS idx_surplus_dup ON surplus_items(service_date, meal)",
    f"""CREATE TABLE IF NOT EXISTS surplus_events (
        id {ID},
        surplus_id INTEGER NOT NULL REFERENCES surplus_items(id),
        at TEXT NOT NULL,
        action TEXT NOT NULL,
        from_status TEXT,
        to_status TEXT,
        actor TEXT NOT NULL DEFAULT 'staff',
        note TEXT NOT NULL DEFAULT ''
    )""",
    "CREATE INDEX IF NOT EXISTS idx_surplus_events ON surplus_events(surplus_id)",
    f"""CREATE TABLE IF NOT EXISTS recipients (
        id {ID},
        name TEXT NOT NULL CHECK (length(name) BETWEEN 1 AND 80),
        contact TEXT NOT NULL DEFAULT '',
        requirements TEXT NOT NULL DEFAULT '',
        min_portions INTEGER CHECK (min_portions IS NULL OR min_portions >= 1),
        max_portions INTEGER CHECK (max_portions IS NULL OR max_portions >= 1),
        active INTEGER NOT NULL DEFAULT 1 CHECK (active IN (0,1)),
        created_at TEXT NOT NULL
    )""",
    # SQLite: name ... COLLATE NOCASE UNIQUE  ->  here: unique ignoring upper/lower case
    "CREATE UNIQUE INDEX IF NOT EXISTS uq_recipients_name_ci ON recipients (lower(name))",
    f"""CREATE TABLE IF NOT EXISTS day_context (
        id {ID},
        date TEXT NOT NULL,
        kind TEXT NOT NULL CHECK (kind IN ('holiday','exam','event','other')),
        meal TEXT CHECK (meal IS NULL OR meal IN {MEAL_LIST}),
        label TEXT NOT NULL DEFAULT '' CHECK (length(label) <= 80),
        created_at TEXT NOT NULL
    )""",
    "CREATE UNIQUE INDEX IF NOT EXISTS uq_context ON day_context (date, kind, (COALESCE(meal, '')), label)",
    "CREATE INDEX IF NOT EXISTS idx_context_date ON day_context(date)",
    f"""CREATE TABLE IF NOT EXISTS anomaly_reviews (
        id {ID},
        date TEXT NOT NULL,
        meal TEXT NOT NULL CHECK (meal IN {MEAL_LIST}),
        kind TEXT NOT NULL,
        status TEXT NOT NULL CHECK (status IN ('reviewed_ok','confirmed_error','dismissed')),
        note TEXT NOT NULL DEFAULT '' CHECK (length(note) <= 300),
        snapshot_prepared INTEGER NOT NULL,
        snapshot_leftovers INTEGER NOT NULL,
        reviewed_at TEXT NOT NULL,
        UNIQUE (date, meal, kind)
    )""",
    f"""CREATE TABLE IF NOT EXISTS forecast_log (
        id {ID},
        target_date TEXT NOT NULL,
        meal TEXT NOT NULL CHECK (meal IN {MEAL_LIST}),
        made_at TEXT NOT NULL,
        method TEXT NOT NULL,
        expected_demand DOUBLE PRECISION NOT NULL,
        recommended INTEGER NOT NULL,
        attendance_pct DOUBLE PRECISION NOT NULL,
        UNIQUE (target_date, meal)
    )""",
]

MIGRATIONS = {1: ("initial EcoPlate schema (same tables as SQLite schema version 1)", MIGRATION_1)}

_VERSION_TABLE = """CREATE TABLE IF NOT EXISTS schema_migrations (
    version INTEGER PRIMARY KEY,
    name TEXT NOT NULL,
    applied_at TEXT NOT NULL
)"""


def migrate(db):
    """Bring the PostgreSQL schema up to SCHEMA_VERSION. `db` is an ecoplate_dbapi.Database (autocommit mode).
    Returns {'from': v0, 'to': v1, 'backup': None}. All-or-nothing: on any error nothing is changed."""
    db.begin()
    try:
        db.execute(f"SELECT pg_advisory_xact_lock({int(LOCK_KEY)})")      # released automatically at COMMIT/ROLLBACK
        db.execute(_VERSION_TABLE)
        v0 = int(db.scalar("SELECT COALESCE(MAX(version), 0) FROM schema_migrations"))
        if v0 > SCHEMA_VERSION:
            raise RuntimeError(f"Database schema version {v0} is newer than this EcoPlate ({SCHEMA_VERSION}). "
                               "Refusing to touch it; update the application instead.")
        result = {"from": v0, "to": v0, "backup": None}
        for target in range(v0 + 1, SCHEMA_VERSION + 1):
            name, statements = MIGRATIONS[target]
            for stmt in statements:
                db.execute(stmt)
            db.execute("INSERT INTO schema_migrations(version, name, applied_at) VALUES(?,?,?)",
                       (target, name, datetime.now(timezone.utc).isoformat(timespec="seconds")))
            result["to"] = target
            log.info("PostgreSQL schema migrated to version %d", target)
        db.commit()
        return result
    except Exception:
        db.rollback()
        raise


def sync_sequences(db):
    """After importing rows WITH their old ids, move every id counter past the largest id, so the next insert
    does not collide. Safe to run any time. Returns {table: the value the counter was set to}."""
    out = {}
    for table in TABLES_WITH_ID:                                           # fixed names from this module, never user input
        out[table] = db.scalar(
            f"SELECT setval(pg_get_serial_sequence('{table}', 'id'), "
            f"COALESCE((SELECT MAX(id) FROM {table}), 1), (SELECT MAX(id) FROM {table}) IS NOT NULL)")
    return out
